-- 0076_translate_content_ar.sql
-- Фаза 28: перевод контента программ — арабский (ar).
-- Переведено вручную с русского оригинала (с опорой на вычитанный
-- английский), с терминологией, принятой в залах этой страны. Английские
-- названия упражнений (Hip Thrust, Mountain Climbers…) оставлены как есть.
-- Применять после 0072. Сопоставление — по точному русскому тексту.
-- Безопасно выполнять повторно.

update public.workout_programs p
set title_ar = v.title, description_ar = v.description
from (values
  ('pohudenie-zhenshchiny-doma', 'خسارة الوزن · نساء · المنزل', 'خسارة الوزن للنساء (في المنزل) — DonatelleX, برنامج لمدة عام. المعدات: دمبلز، أحبال مطاطية بمقاومات مختلفة، سجادة، منصة/درجة ثابتة (إن أمكن)'),
  ('pohudenie-zhenshchiny-zal', 'خسارة الوزن · نساء · الجيم', 'خسارة الوزن للنساء (في الجيم) — برنامج لمدة عام. المعدات: مشاية، إليبتيكال/جهاز التزلج، أجهزة، دمبلز، كابلات، سجادة'),
  ('nabor-massy-zhenshchiny-doma', 'بناء العضلات · نساء · المنزل', 'بناء العضلات للنساء (في المنزل) — برنامج لمدة عام. المعدات: دمبلز، أحبال مطاطية بمقاومات مختلفة، سجادة، منصة/درجة ثابتة'),
  ('nabor-massy-zhenshchiny-zal', 'بناء العضلات · نساء · الجيم', 'بناء العضلات للنساء (في الجيم) — برنامج لمدة عام «12 LEVELS». المعدات: بار، دمبلز، أجهزة (Hip Thrust، Hack Squat، Leg Press، كابلات)، أحبال مطاطية، كيتل بيل، TRX، كرة طبية'),
  ('pohudenie-muzhchiny-doma', 'خسارة الوزن · رجال · المنزل', 'خسارة الوزن للرجال (في المنزل) — برنامج لمدة عام. المعدات: دمبلز، أحبال مطاطية، بار العقلة (إن أمكن)، كرسي/بنش، سجادة'),
  ('pohudenie-muzhchiny-zal', 'خسارة الوزن · رجال · الجيم', 'خسارة الوزن للرجال (في الجيم) — برنامج لمدة عام. المعدات: بار، دمبلز، أجهزة، كابلات، Battle Rope، SkiErg/جهاز التجديف، منطقة الكارديو (مشاية/إليبتيكال/دراجة ثابتة)'),
  ('nabor-massy-muzhchiny-doma', 'بناء العضلات · رجال · المنزل', 'بناء العضلات للرجال (في المنزل) — برنامج لمدة عام. المعدات: دمبلز، أحبال مطاطية، بار العقلة (إن أمكن)، كرسي/بنش، سجادة'),
  ('nabor-massy-muzhchiny-zal', 'بناء العضلات · رجال · الجيم', 'بناء العضلات للرجال (في الجيم) — برنامج لمدة عام. المعدات: صالة كاملة: بارات، دمبلز، أجهزة، بار العقلة، حبال، TRX، كيتل بيل'),
  ('nabor-massy-nachinayushchim', 'بناء العضلات للمبتدئين', 'أول برنامج للرجال الذين يريدون البدء في بناء العضلات في الجيم. دورة من 7 أيام: 4 تمارين قوة لمجموعات عضلية مختلفة و3 أيام كارديو خفيف مع تمارين البطن. مناسب للمبتدئين — بدون تقنيات معقدة، والتركيز على الحجم والأداء الصحيح.')
) as v(slug, title, description)
where p.slug = v.slug;

